private struct EditorPlaceholderExpansionData {
  let displayText: String
  let typeForExpansion: TypeSyntax?

  init?(token: TokenSyntax) {
    guard let rawData = token.rawEditorPlaceHolderData else {
      return nil
    }

    if let typeText = rawData.typeForExpansionText, !typeText.isEmpty {
      self.displayText = then(syntaxText: typeText)
      var parser = Parser(UnsafeBufferPointer(start: typeText.baseAddress, count: typeText.count))
      let type: TypeSyntax = TypeSyntax.parse(from: &parser)
      self.typeForExpansion = type.hasError ? nil : type
    } else {
      self.displayText = String(syntaxText: rawData.for)
      self.typeForExpansion = nil
    }
  }
}
struct ContainmentRule: DisambiguationRule {
    var isHardConstraint: Bool { true }
    /// One entry per annotation; the containers inside an entry are alternatives.
    let groups: [[() -> Set<BinarySpan>]]
    let negated: Bool
    func prune(_ yields: inout Set<BinarySpan>) -> Int {
        let gys = groups.map { $0.map { $0() } }
        var pruned = 0
        for span in yields {
            // Every group must contain the span in at least one of its containers.
            let contained = gys.allSatisfy { group in
                group.contains
{ cy in cy.contains { $0.i <= span.i && span.j <= $0.j } }
            }
            if contained == negated { yields.remove(span); pruned += 1 }   // confinedTo prunes ¬contained; excludedFrom prunes contained
        }
        return pruned
    }
}
